import DodoPayments from 'dodopayments';

const client = new DodoPayments({
  bearerToken: process.env['DODO_PAYMENTS_API_KEY'], // This is the default and can be omitted
});

const addonResponse = await client.addons.create({
  currency: 'AED',
  name: 'name',
  price: 0,
  tax_category: 'digital_products',
});

console.log(addonResponse.id);

package main

import (
	"context"
	"fmt"

	"github.com/dodopayments/dodopayments-go"
	"github.com/dodopayments/dodopayments-go/option"
)

func main() {
	client := dodopayments.NewClient(
		option.WithBearerToken("My Bearer Token"),
	)
	addonResponse, err := client.Addons.New(context.TODO(), dodopayments.AddonNewParams{
		Currency:    dodopayments.F(dodopayments.CurrencyAed),
		Name:        dodopayments.F("name"),
		Price:       dodopayments.F(int64(0)),
		TaxCategory: dodopayments.F(dodopayments.TaxCategoryDigitalProducts),
	})
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", addonResponse.ID)
}

package com.dodopayments.api.example;

import com.dodopayments.api.client.DodoPaymentsClient;
import com.dodopayments.api.client.okhttp.DodoPaymentsOkHttpClient;
import com.dodopayments.api.models.addons.AddonCreateParams;
import com.dodopayments.api.models.addons.AddonResponse;
import com.dodopayments.api.models.misc.Currency;
import com.dodopayments.api.models.misc.TaxCategory;

public final class Main {
    private Main() {}

    public static void main(String[] args) {
        DodoPaymentsClient client = DodoPaymentsOkHttpClient.fromEnv();

        AddonCreateParams params = AddonCreateParams.builder()
            .currency(Currency.AED)
            .name("name")
            .price(0)
            .taxCategory(TaxCategory.DIGITAL_PRODUCTS)
            .build();
        AddonResponse addonResponse = client.addons().create(params);
    }
}

using System;
using DodoPayments.Client;
using DodoPayments.Client.Models.Addons;
using DodoPayments.Client.Models.Misc;

DodoPaymentsClient client = new();

AddonCreateParams parameters = new()
{
    Currency = Currency.Aed,
    Name = "name",
    Price = 0,
    TaxCategory = TaxCategory.DigitalProducts,
};

var addonResponse = await client.Addons.Create(parameters);

Console.WriteLine(addonResponse);

use dodopayments::Client;

#[tokio::main]
async fn main() -> dodopayments::Result<()> {
    let client = Client::from_env()?;
    let result = client
        .addons()
        .create()
        .body(dodopayments::models::AddonsCreateParams {
                currency: Some(Box::new(dodopayments::models::Currency::Aed)),
                name: Some("name".to_string()),
                price: Some(0),
                tax_category: Some(Box::new(dodopayments::models::TaxCategory::DigitalProducts)),
                ..Default::default()
            })
        .await?;
    println!("{result:?}");
    Ok(())
}

